{
  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError("case must contain 'nodes' and 'required_symbols'")
    nodes_data = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes_data, list) or not isinstance(required_symbols, list):
        raise ValueError("nodes must be list, required_symbols must be list")

    node_map = {}
    children_map = {}
    for node in nodes_data:
        if not isinstance(node, dict):
            raise ValueError("each node must be a dict")
        nid = node.get('id')
        parent = node.get('parent')
        symbol = node.get('symbol')
        removable = node.get('removable')
        if nid is None or symbol is None or removable is None:
            raise ValueError("node missing required fields (id, symbol, removable)")
        node_map[nid] = node
        children_map.setdefault(parent, []).append(nid)

    root_id = None
    for nid, node in node_map.items():
        if node['parent'] is None:
            root_id = nid
            break
    if root_id is None:
        raise ValueError("no root node with parent None")
    root_node = node_map[root_id]
    if root_node.get('removable') is True:
        raise ValueError("root node is removable")

    symbol_counts = {}
    for nid, node in node_map.items():
        sym = node['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1

    removable_nodes = [node for node in nodes_data if node['removable'] is True and node['id'] != root_id]
    removable_nodes.sort(key=lambda n: (-n['depth'], n['id']))

    removed_set = set()
    removal_order = []

    for node in removable_nodes:
        nid = node['id']
        if nid in removed_set:
            continue
        sym = node['symbol']
        cur_count = symbol_counts.get(sym, 0)
        if sym in required_symbols and cur_count - 1 < 1:
            continue
        children = children_map.get(nid, [])
        has_retained_child = any(child_id not in removed_set for child_id in children)
        if has_retained_child:
            continue
        removed_set.add(nid)
        symbol_counts[sym] = cur_count - 1
        removal_order.append(nid)

    retained_ids = [node['id'] for node in nodes_data if node['id'] not in removed_set]
    retained_ids.sort()

    return {
        "removed_node_ids": removal_order,
        "retained_node_ids": retained_ids
    }"
}
